insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('gestao-de-lixo','Gestão de lixo','Meio ambiente','O desafio da gestão de lixo na contemporaneidade brasileira.',100,'published','{"focus": "O desafio da gestão de lixo na contemporaneidade brasileira.", "axes": ["Infraestrutura de coleta e destinação dos resíduos", "Consumo e cultura do desperdício"], "repertoire": [{"title": "Lixo Extraordinário / Vik Muniz", "application": "Relacione a visibilidade do trabalho dos catadores à valorização da reciclagem, como sugere a aula."}], "exercise": "Escreva um parágrafo que explique como a falta de coleta adequada produz um impacto social. Acrescente uma frase ligando o repertório à explicação.", "intervention": "Prefeituras podem ampliar a coleta seletiva em parceria com cooperativas, com rotas e pontos de coleta definidos, para melhorar a destinação dos resíduos.", "pitfalls": ["Não use uma citação só porque ela parece sofisticada: a própria aula traz um exemplo de repertório improdutivo.", "Diferencie a geração de resíduos das falhas na destinação."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
