insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('nomofobia','Nomofobia','Tecnologia','Impactos da nomofobia no contexto brasileiro contemporâneo.',101,'published','{"focus": "Impactos da nomofobia no contexto brasileiro contemporâneo.", "axes": ["Dependência de conexão e hábitos digitais", "Prejuízos ao convívio e à autonomia"], "repertoire": [{"title": "Her (Ela)", "application": "Use a relação com a tecnologia como analogia para discutir vínculos humanos; explique os limites dessa comparação com a nomofobia."}], "exercise": "Crie uma tese com dois eixos. Depois escreva três frases que distingam uso frequente de celular e dependência prejudicial.", "intervention": "Escolas, em diálogo com famílias, podem desenvolver atividades de educação digital e convivência presencial, para incentivar hábitos equilibrados.", "pitfalls": ["Não trate todo usuário frequente como uma pessoa com transtorno.", "Evite transformar o texto em uma condenação genérica da tecnologia."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
