insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('dependencia-quimica','Dependentes químicos','Saúde','Impasses para o tratamento de dependentes químicos no Brasil.',102,'published','{"focus": "Impasses para o tratamento de dependentes químicos no Brasil.", "axes": ["Estigma que dificulta o acolhimento", "Barreiras de acesso e continuidade do cuidado"], "repertoire": [{"title": "Quebrando o Tabu", "application": "A partir do documentário indicado, formule uma pergunta sobre como diferentes abordagens lidam com o problema."}], "exercise": "Escreva dois tópicos frasais diferentes: um sobre estigma e outro sobre acesso ao tratamento. Explique uma consequência de cada um.", "intervention": "Gestores de saúde podem ampliar o acolhimento e o acompanhamento, articulando equipes e serviços para facilitar a continuidade do cuidado.", "pitfalls": ["Mantenha o recorte no tratamento; não substitua o tema por uma discussão apenas sobre criminalidade.", "Use linguagem respeitosa e não culpabilize quem precisa de cuidado."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
