insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('patrimonio','Patrimônio histórico e cultural','Cultura','A importância da preservação do patrimônio histórico e cultural brasileiro.',103,'published','{"focus": "A importância da preservação do patrimônio histórico e cultural brasileiro.", "axes": ["Conservação do patrimônio material", "Transmissão de saberes e valorização da memória"], "repertoire": [{"title": "Patrimônio material e imaterial", "application": "Use a distinção apresentada na aula para explicar por que preservar envolve edifícios e também práticas culturais."}], "exercise": "Escolha um exemplo material e um imaterial da sua região. Explique como cada um sustenta uma tese sobre memória coletiva.", "intervention": "Órgãos de cultura podem promover projetos de preservação com participação das comunidades e ações educativas, para manter referências culturais acessíveis.", "pitfalls": ["Não restrinja patrimônio a construções antigas.", "Relacione o exemplo escolhido ao valor da preservação, sem apenas descrevê-lo."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
