insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('mulheres-na-ciencia','Mulheres na Ciência','Cidadania','Os desafios enfrentados pelas mulheres cientistas no Brasil.',104,'published','{"focus": "Os desafios enfrentados pelas mulheres cientistas no Brasil.", "axes": ["Estereótipos e reconhecimento científico", "Sobrecarga de cuidados e permanência na carreira"], "repertoire": [{"title": "Apagamento histórico", "application": "Parta da discussão da aula para explicar como o reconhecimento desigual afeta referências e oportunidades."}], "exercise": "Desenvolva um argumento sobre reconhecimento e outro sobre condições de permanência. Escreva uma intervenção que enfrente uma dessas barreiras.", "intervention": "Universidades e instituições de pesquisa podem fortalecer programas de mentoria e apoio à permanência, com critérios transparentes e acompanhamento.", "pitfalls": ["Mantenha o foco na carreira científica, sem se limitar ao mercado de trabalho em geral.", "Evite listar cientistas sem explicar a relação delas com o argumento."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
