insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('ist','IST e juventude','Saúde','O desafio do aumento de ISTs entre jovens na sociedade brasileira.',105,'published','{"focus": "O desafio do aumento de ISTs entre jovens na sociedade brasileira.", "axes": ["Barreiras à informação e à educação em saúde", "Estigma e dificuldades de acesso aos serviços"], "repertoire": [{"title": "Estigma e saúde pública", "application": "Use a discussão do material para explicar como preconceitos podem dificultar a busca por informação e acolhimento."}], "exercise": "Escreva uma tese sem julgamento moral. Depois apresente dois caminhos de educação e acesso à informação que dialoguem com ela.", "intervention": "Equipes de saúde, em parceria com escolas, podem realizar ações educativas com linguagem adequada ao público e orientação para os serviços disponíveis.", "pitfalls": ["Use a terminologia IST e explique o recorte do tema.", "Dados antigos da aula devem ser identificados pelo ano; não os apresente como retrato atual."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
