insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('racismo-ambiental','Racismo ambiental','Meio ambiente','Desafios para combater o racismo ambiental no Brasil.',106,'published','{"focus": "Desafios para combater o racismo ambiental no Brasil.", "axes": ["Distribuição desigual de riscos ambientais", "Invisibilidade e fragmentação das respostas públicas"], "repertoire": [{"title": "Justiça ambiental", "application": "Explique como a exposição desigual a riscos se relaciona com desigualdades raciais e territoriais, conforme a aula."}], "exercise": "Crie um argumento que conecte território, exposição ao risco e raça. Revise se os três elementos aparecem na explicação.", "intervention": "Gestores locais podem mapear riscos com participação das comunidades e priorizar ações de saneamento e prevenção nas áreas mais expostas.", "pitfalls": ["Não reduza o tema à poluição em geral; mantenha a dimensão racial.", "Evite responsabilizar comunidades por condições que limitam suas escolhas."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
