insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('inteligencia-artificial','Inteligência artificial','Tecnologia','Perspectivas acerca do uso da inteligência artificial na sociedade brasileira.',107,'published','{"focus": "Perspectivas acerca do uso da inteligência artificial na sociedade brasileira.", "axes": ["Oportunidades de uso e desigualdade de acesso", "Responsabilidade e avaliação dos impactos"], "repertoire": [{"title": "Revolução Industrial", "application": "Use a analogia sugerida no material para discutir transformações sociais, explicando uma semelhança e um limite da comparação."}], "exercise": "Escolha um setor, como educação ou trabalho. Escreva um benefício possível e um risco, e formule uma tese que estabeleça uma condição de uso responsável.", "intervention": "Instituições de ensino podem desenvolver formação em uso crítico da IA, com atividades de verificação de informações e discussão de seus limites.", "pitfalls": ["Evite tratar ficção como prova empírica.", "Delimite o setor e os efeitos discutidos; não prometa explicar toda a tecnologia."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
