insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('automedicacao','Automedicação','Saúde','A questão da automedicação no Brasil e seus efeitos para a saúde pública.',108,'published','{"focus": "A questão da automedicação no Brasil e seus efeitos para a saúde pública.", "axes": ["Dificuldades de acesso à orientação profissional", "Circulação de informações sem avaliação crítica"], "repertoire": [{"title": "Direito à saúde", "application": "A partir da abordagem do material, conecte acesso à orientação e cuidado à responsabilidade coletiva na saúde."}], "exercise": "Produza um parágrafo sobre as condições sociais do problema. Retire generalizações como “as pessoas são irresponsáveis” e substitua por mecanismos explicados.", "intervention": "Serviços de saúde podem ampliar ações de orientação sobre uso responsável de medicamentos e divulgar canais de atendimento acessíveis à população.", "pitfalls": ["O exercício é argumentativo: não inclua recomendações de medicamentos ou doses.", "Confira autoria, data e fonte antes de reproduzir dados e referências normativas da aula."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
