insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('saude-mental-esporte','Saúde mental no esporte','Saúde','Prejuízos da ausência de discussão sobre saúde mental no âmbito esportivo.',109,'published','{"focus": "Prejuízos da ausência de discussão sobre saúde mental no âmbito esportivo.", "axes": ["Pressão por desempenho e silêncio sobre sofrimento", "Acesso a apoio e condições de acolhimento"], "repertoire": [{"title": "Cultura do desempenho", "application": "Use o recorte esportivo apresentado na aula para explicar a tensão entre resultados e bem-estar."}], "exercise": "Escreva uma introdução em que o esporte apareça explicitamente. Desenvolva um argumento sobre silêncio e outro sobre apoio institucional.", "intervention": "Clubes e entidades esportivas podem organizar acompanhamento e canais de acolhimento, com profissionais qualificados e respeito à privacidade dos atletas.", "pitfalls": ["Não transforme o recorte em saúde mental de toda a população.", "Não faça diagnósticos de atletas a partir de relatos ou desempenho."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
