insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('protecao-infantojuvenil','Combate à exploração sexual','Cidadania','Os desafios para o combate à exploração sexual de crianças e adolescentes no Brasil contemporâneo.',110,'published','{"focus": "Os desafios para o combate à exploração sexual de crianças e adolescentes no Brasil contemporâneo.", "axes": ["Silenciamento e naturalização da violência", "Fragilidades da rede de proteção"], "repertoire": [{"title": "Cultura do silêncio", "application": "Use o conceito discutido no material para explicar por que reconhecer e enfrentar a violência exige respostas coletivas."}], "exercise": "Formule dois argumentos centrados na proteção. Escreva uma proposta que detalhe o papel de uma instituição sem transferir a responsabilidade à vítima.", "intervention": "A rede de proteção, em parceria com escolas e serviços públicos, pode fortalecer ações educativas e fluxos de acolhimento com profissionais capacitados.", "pitfalls": ["Preserve a dignidade das vítimas e dispense descrições gráficas.", "Evite propostas que culpabilizem crianças e adolescentes."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
