insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('autismo','Inclusão de pessoas com autismo','Cidadania','Dificuldades para a inclusão social de pessoas com autismo no Brasil.',111,'published','{"focus": "Dificuldades para a inclusão social de pessoas com autismo no Brasil.", "axes": ["Preconceito e barreiras à participação social", "Acessibilidade e preparação das instituições"], "repertoire": [{"title": "Inclusão e acessibilidade", "application": "Explique a diferença entre permitir a presença e criar condições reais de participação, a partir da discussão da aula."}], "exercise": "Escolha escola ou trabalho. Descreva uma barreira concreta, sua consequência e uma medida que permita participação com autonomia.", "intervention": "Instituições podem qualificar equipes e adaptar práticas com participação das pessoas autistas e de suas redes de apoio, respeitando necessidades diversas.", "pitfalls": ["Não apresente pessoas autistas como um grupo homogêneo.", "Foque na remoção de barreiras, sem propor a eliminação de características pessoais."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
