insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('seguranca-publica','Segurança pública','Cidadania','Caminhos possíveis para a melhoria da segurança pública no Brasil.',112,'published','{"focus": "Caminhos possíveis para a melhoria da segurança pública no Brasil.", "axes": ["Prevenção e acesso a oportunidades", "Reintegração social e atuação institucional"], "repertoire": [{"title": "Capitães da Areia", "application": "O material aproxima a obra da discussão sobre marginalização; explique a ligação com prevenção, sem associar pobreza automaticamente a crime."}], "exercise": "Escreva uma tese que articule prevenção e resposta institucional. Para cada eixo, explique como a medida proposta poderia enfrentar o problema.", "intervention": "Gestores públicos podem articular ações de prevenção e acompanhamento social com metas e avaliação, priorizando os problemas identificados no território.", "pitfalls": ["Não trate uma proposta legislativa citada como uma lei já vigente.", "Evite soluções que violem direitos ou estigmatizem grupos sociais."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
