insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('saude-bucal','Saúde bucal','Saúde','Desigualdades no acesso à saúde bucal: um entrave à cidadania brasileira.',113,'published','{"focus": "Desigualdades no acesso à saúde bucal: um entrave à cidadania brasileira.", "axes": ["Desigualdade no acesso aos serviços", "Invisibilidade dos efeitos sociais do problema"], "repertoire": [{"title": "Cidadania e acesso ao cuidado", "application": "Use o recorte da aula para relacionar o acesso ao atendimento às condições de participação social."}], "exercise": "Escreva um argumento que vá além da higiene individual. Relacione uma barreira de acesso a uma consequência social.", "intervention": "Gestores de saúde podem ampliar o atendimento odontológico e as ações de orientação, com organização de equipes e prioridades de acesso.", "pitfalls": ["Mantenha a desigualdade de acesso no centro da tese.", "Ao usar estatísticas do material, identifique o ano e verifique a fonte."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
