insert into public.essay_course_modules(slug,title,category,description,sort_order,status,learning_content) values ('educacao-financeira','Educação financeira','Educação','A importância da educação financeira na vida do brasileiro.',114,'published','{"focus": "A importância da educação financeira na vida do brasileiro.", "axes": ["Acesso à formação e compreensão de informações", "Consumo e condições sociais das decisões"], "repertoire": [{"title": "Vidas Secas", "application": "Use a discussão sobre Fabiano para relacionar letramento, vulnerabilidade e compreensão de relações econômicas, sem culpar quem tem menor renda."}], "exercise": "Produza dois tópicos frasais: um sobre formação e outro sobre contexto social. Explique por que informação sozinha não resolve todas as desigualdades.", "intervention": "Escolas podem desenvolver atividades contextualizadas de educação financeira, com situações de consumo e leitura crítica de informações adequadas à faixa etária.", "pitfalls": ["Não apresente pobreza como resultado apenas de falta de planejamento.", "Diferencie educação financeira de indicação de investimentos."], "checklist": ["Minha tese responde ao recorte completo do tema.", "Cada argumento tem uma explicação e uma relação com a tese.", "Expliquei a função do repertório no parágrafo.", "A intervenção enfrenta o problema que desenvolvi.", "Revisei conectivos, pontuação e repetições."]}'::jsonb) on conflict(slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,sort_order=excluded.sort_order,learning_content=excluded.learning_content,updated_at=now();
